#!/usr/bin/env python3
# Source of truth for the chatbot Q&A. Run: python3 docs/chatbot/build_qna.py docs/chatbot
import json, sys, os

SYSTEM = (
    "You are the help assistant inside KitchenDesignBiz, a kitchen design and quoting app. "
    "Answer in short, exact steps using the button names shown on screen. "
    "Only describe features that exist; if something isn't possible, say so and give the workaround. "
    "If the question is unclear, ask one short question."
)

QA = [
('A', 'I just logged in. Where do I start?',
 'Start on **Home**. It shows what needs attention today.\n\n- **Starting a new kitchen?** Press **New customer** (top right), fill in their details, then open their design from the **Customers** page.\n- **Continuing one?** Pick it under **Continue designing** on Home.\n\nIf this is your first time, set up your business first: **Settings** (name, logo), **Rate card** (your prices), **Catalogue** and **Workshop**.'),
('A', 'what are all these pages on the left?',
 "- **Home**: today's follow-ups and recent designs.\n- **Customers**: all customers by stage; open their designs here.\n- **Production**: approved jobs for the workshop.\n- **Catalogue**: your cabinets, appliances, finishes, handles, lights and pillar sizes.\n- **Rate card**: your prices.\n- **Workshop**: how your carpenter builds cabinets.\n- **Settings**: business details, logo, sign out.\n\nOn a phone, Home, Customers, Production and Catalogue are tabs at the bottom; the rest are under **More**."),
('A', 'how do I go back to the list of customers from the design?',
 'Click the **←** arrow at the top left of the design screen. It takes you back to **Customers**.'),
('A', "Is there a save button? I'm scared I'll lose my work",
 "You don't need one: the design saves by itself a moment after every change. The top bar shows **Saved**. If it ever says **Not saved**, check your internet and click **Not saved** to try again. A red message under the top bar explains what went wrong."),
('A', 'how to undo',
 'Use the **↶ Undo** button at the bottom left of the design screen (**↷** is Redo). Or press **Ctrl+Z** (Cmd+Z on Mac); redo is **Ctrl+Shift+Z**.\n\nOn a phone there are no undo buttons, so use a laptop or change it back by hand.'),
('A', 'everything is in mm? i measure in feet',
 'Yes, every size in the app is in millimetres. Quick conversions:\n\n- 1 foot ≈ 305 mm, 1 inch ≈ 25 mm.\n- 10 ft ≈ 3050 mm; 8 ft ≈ 2440 mm.\n- A 2 ft cabinet ≈ 600 mm.'),
('A', 'Can I use this on my phone?',
 'Yes. On a phone the design tools sit in a strip at the bottom, and **Cutting list**, **Quote** and **Present** are in the **…** menu at the top right. There are no undo buttons on a phone, and dragging is fiddly on a small screen, so a laptop is best for designing. A phone works well for Home, Customers, Production and sending quotes.'),
('A', 'where do i see total price of kitchen while designing',
 'Look at **Total** at the bottom right of the design screen; it updates live as you design. Click it to open the full quote with every line.'),
('A', "too many options I'm confused what to do next on this kitchen",
 "Go in this order on the design screen:\n\n1. **Room**: set the size.\n2. **Pillars** and **Doors**: add pillars, doors and windows.\n3. **Style**: choose the finishes.\n4. **Cabinets**, then **Appliances**.\n5. **Surfaces**: floor, walls, countertop.\n6. Fix anything in the checks button at the bottom left.\n7. Look at it in **3D**, then **Finalise quote**.\n\nTell me which step you're on and I'll walk you through it."),
('B', 'How do I add a new customer?',
 '1. Go to **Home** or **Customers** and press **New customer**.\n2. Fill in **Name**, **Phone**, **Address** and **Locality**; **Notes** are optional and only your team sees them.\n3. Press **Add customer**.\n\nThey start as a **Lead**. Their card is on the **Customers** page, where you open their design.'),
('B', 'naya customer kaise banaye',
 '**Home** ya **Customers** page par **New customer** dabayiye. Name, Phone, Address, Locality bhariye, phir **Add customer**. Customer **Lead** stage mein aa jayega. Unka design **Customers** page par unke card se khulega.'),
('B', 'how do I start the kitchen design for a customer I already added',
 "1. Go to **Customers**.\n2. Find their card (use the search box if needed).\n3. Click the customer's name on the card. The design screen opens.\n\nOr use the card's **…** menu → **Open design**. On **Home**, **Start design** in the Follow up list does the same."),
('B', "I can't find my customer",
 "On **Customers**, type their name, phone or locality in the search box.\n\nIf they still don't show:\n- **Lost customers** are under the **Lost (n)** filter.\n- **Installed jobs** leave the board after a while; switch to **List** view to see them."),
('B', 'how to move customer to quote sent',
 "On **Customers**, drag their card into the **Quote sent** column. Or open the card's **…** menu → **Move to** → **Quote sent**."),
('B', 'customer said yes, what do I do in the app',
 '1. Move them to **Approved**: on **Customers**, drag the card to **Approved**, or use **…** → **Move to** → **Approved**.\n2. The job now appears on **Production**. From there you can **Set install date**, open the **Cutting list**, and press **Start production**.\n3. After fitting, press **Mark installed**.\n\nGive the workshop the cutting list for the quote version the customer approved.'),
('B', 'how do I delete a customer',
 "Customers can't be deleted. To take one off the board, move them to **Lost**: card **…** → **Move to** → **Lost**, and give a reason. They stay under the **Lost (n)** filter for your records. To correct their details instead, use **…** → **Edit details**."),
('B', 'I typed the wrong phone number for a customer, how to edit',
 "1. Go to **Customers**.\n2. Open the customer's card menu **…** → **Edit details**.\n3. Correct the **Name**, **Phone**, **Address** or **Locality**.\n4. Press **Save details**."),
('B', 'where do I write notes about the customer like budget',
 "Use the card's **…** menu on **Customers** → **Notes** (or **Add notes**), type, then **Save notes**. Notes are only for your team; they never appear on a quote. The first line shows on the card."),
('B', 'set installation date where',
 'Either:\n- **Production** page → on the job, press **Set install date** (or the date, to change it).\n- **Customers** → card **…** → **Set install date**.\n\nThis works once the customer is **Approved** or **In production**. Upcoming installs show on **Home**.'),
('B', 'what do the stages mean',
 "- **Lead**: enquiry, no design yet.\n- **Layout drafted**: you've started the design.\n- **Quote sent**: they have a frozen quote.\n- **Approved**: they said yes; the job shows on Production.\n- **In production**: the workshop is building.\n- **Installed**: fitted on site.\n- **Lost**: didn't go ahead."),
('C', 'how to set room size',
 "1. Open the customer's design.\n2. Press **Room** in the top bar.\n3. Enter **Width — L (mm)**, **Depth — B (mm)** and **Ceiling Height — H (mm)**.\n4. Press **Apply**.\n\nShrinking the room doesn't move items that end up outside it; drag them back in."),
('C', 'my kitchen is 10 by 8 feet what do I type',
 'Press **Room** in the top bar and enter about **3050** for one side and **2440** for the other (1 ft ≈ 305 mm), then **Apply**. Width is east–west, depth is north–south on the plan.'),
('C', 'there is a pillar in the corner how do I add it',
 '1. Click **Pillars** on the left tool rail.\n2. Drag a size from **Your presets** onto the plan. Or use **Custom size**: choose the **Type** and size, tick **Floor to ceiling** if it is one, and press **+ Add …**.\n3. Select it to fine-tune: **X (mm)** and **Y (mm)** for the exact position, **Width (mm)** and **Depth (mm)** for the size.'),
('C', 'how to add a windw',
 "1. Click **Doors** on the left tool rail.\n2. In the **Window** row, press the wall it's on: **North wall**, **East wall**, **South wall** or **West wall**.\n3. Select the window and set **Along wall (mm)**, **Width**, **Height** and **Sill** (height of its bottom edge from the floor). You can also drag it along the wall."),
('C', 'add door to kitchen',
 "Click **Doors** on the left, then in the **Door** row press the wall it's on (**North wall**, **East wall**, **South wall** or **West wall**). Select it to set **Along wall (mm)**, **Width**, **Height** and **Swing**. Keep **Sill** at 0 for a door. An in-swinging door keeps its swing area clear of cabinets."),
('C', 'which side is north on the plan',
 'On the plan, **north is the top edge**, east is right, south is the bottom, west is left. These are just names for the walls, not real compass directions. Pick whichever wall matches the drawing.'),
('C', 'the door is on the wrong wall',
 'Doors and windows stay on the wall they were added to. Select it, press **Delete** in its settings, then add it again from **Doors** with the right wall button.'),
('C', 'do I get charged for window in quote? it already exists',
 'No. Doors and windows are treated as already in place and print on the quote at ₹0. Only if you supply one yourself, select it, tick **Supplied by you** and enter its **Price**.'),
('D', 'where do I find cabinets to add',
 'Click **Cabinets** on the left tool rail of the design screen. Search, or use the category chips (e.g. Base, Wall, Tall), then **drag a tile onto the plan**. It turns to face the room and snaps to the wall. Clicking a tile instead adds it in the middle of the room.'),
('D', 'how do I add a wall cabinet above the base one',
 "Open **Cabinets**, choose a wall cabinet (the **Wall** chip, if your catalogue uses it) and drag it onto the plan over the base cabinet. It's placed at wall-cabinet height automatically. To adjust, select it and change **Height off the floor**."),
('D', 'how to move a cabinet',
 'Drag it on the plan; it snaps to a 50 mm grid and to neighbouring cabinets. For small moves, select it and use the arrow keys (10 mm each; Shift + arrow moves 50 mm).'),
('D', 'cabinet ghumana kaise hai',
 'Double-click it on the plan; each double-click turns it 90°. Shift + double-click turns it the other way. Or select it and press **Turn left** / **Turn right** at the top of its settings.'),
('D', 'double click is rotating the sink not the sink cabinet',
 'The sink sits on top, so it gets the double-click. To turn the cabinet:\n\n1. Click the sink area; a list **"2 items here"** appears.\n2. Choose the sink unit (cabinet).\n3. Now double-click; the selected cabinet turns.\n\nOr choose the cabinet from the list and press **Turn left** / **Turn right** in its settings.'),
('D', 'ye cabinet delete kaise karu',
 'Select it, then either press **Delete** at the top of its settings (right side), or press the **Delete** or **Backspace** key. Changed your mind? **Undo** (Ctrl+Z).'),
('D', 'cabinet ki copy kaise banaye',
 'Select the cabinet and press **Duplicate** at the top of its settings. Or press **Ctrl+C** then **Ctrl+V** (Cmd on Mac). The copy appears next to it, already selected; drag it into place.'),
('D', "I selected a cabinet but I don't see its settings anywhere",
 'Look at the **right edge** of the screen: a slim tab with the item type (e.g. "Cabinet"). Move your mouse onto it, or tap it, and the full settings slide out. If the Quote panel is open, the settings show in that column instead.'),
('H', "I don't want the customer to see my margin on the quote",
 "They never see it. Your margin is built into each line's price, so the quote, the PDF and Present show only selling prices; no margin line appears anywhere. Nothing needs to be hidden or changed.\n\n**Your pricing** in the quote panel (with its **Cost** view) is visible only to you."),
('D', 'chnage width of cabinet',
 'Select the cabinet, open its settings from the right edge, and under **Size** change **Width** (also Depth and Height). Then press **Apply new size**.'),
('D', 'how to change the colour of one cabinet',
 '1. Select the cabinet and open its settings from the right edge.\n2. Tap the **Finish** row.\n3. Pick a finish. To change the shade, under **Colour** choose **Custom shade** and pick a colour, or type a hex code (e.g. c08a4e).\n\nTo change all cabinets at once, use **Style** in the top bar instead.'),
('D', 'i want all base cabinets in walnut and wall cabinets white',
 'Use **Style** in the top bar:\n\n1. On the **Base cabinets** tab, pick the walnut finish.\n2. On the **Wall cabinets** tab, pick white.\n\nEvery cabinet still on the old default changes. If some were set by hand, a message offers **Change them too**. New cabinets take these defaults automatically.'),
('D', 'how to make a cabinet drawers instead of doors',
 'Select the cabinet, open its settings, and under **Front** choose **Drawers**. Then set **Number of drawers**.'),
('D', 'I want 1 drawer on top and doors below in same cabinet',
 "Select the cabinet. Under **Front**, choose **Mixed (stacked rows)**. Set the top row to **Drawers** (1) and the next row to **Double door** or **Single door**. Use **Height share** to set each row's height, and **+ Add row** to add more rows."),
('D', 'change handle of cabinet',
 'Select the cabinet. In its settings under **Front**, change **Handle**. To change handles for the whole kitchen, use **Style** → **Handle** (per base, wall and tall cabinets).'),
('D', 'wall cabinet is too low how to raise it',
 'Select it and change **Height off the floor** in its settings (in mm, measured to the bottom of the cabinet). 0 means it stands on the floor.'),
('D', 'corner cabinet showing overlap error with the next cabinet',
 "For a blind or magic corner unit:\n\n1. Select it.\n2. Under **Fixed corner panel**, press **Fit to corner**.\n\nThe part hidden behind the other wall's cabinets becomes a fixed panel, the door moves beside it, and its door no longer swings into the next cabinet. You can also choose **Left end** / **Right end** and set **Panel width (mm)** yourself.\n\nIf the two cabinets' boxes actually overlap on the plan, drag them apart; the fixed panel only fixes the door clash."),
('D', "the cabinet I want isn't in the list",
 'Add it to your catalogue:\n\n1. In the **Cabinets** panel, press **Manage catalogue** (or go to **Catalogue** → **Cabinets**).\n2. Press **New cabinet**, fill in name, type, size, finish, front and price, and press **Add cabinet**.\n3. Press **Back to … kitchen** (bottom right) to return to your design.\n\nOr place a similar cabinet and change its size.'),
('D', 'add extra shelf inside cabinet',
 'Select the cabinet → **Panels & boards…** → set **Extra shelves** → **Save** → **← Back**. The shelves appear on the cutting list and are priced.'),
('D', "it's showing a warning but I want the cabinet there on purpose",
 'Select the cabinet. At the bottom of its settings, open **More: design checks for this item** and tick **Ignore overlap alerts** or **Ignore door/drawer clearance alerts**. It only silences that one cabinet.'),
('E', 'where are hob chimney sink',
 'Click **Appliances** on the left tool rail. Drag the hob, chimney, sink, fridge and so on onto the plan. Each one is placed at the height set for it in your catalogue (e.g. a hob on the counter, a chimney above it). To adjust, select it and change **Off floor (mm)**.'),
('E', 'chimney is at wrong height',
 'Select the chimney and change **Off floor (mm)**: the height of its bottom edge from the floor. About 850 is counter level; a chimney usually goes around 1500–1650, about 650–750 above the hob.'),
('E', 'how to copy the same hob again',
 'Appliances have no Duplicate button. Select it and press **Ctrl+C** then **Ctrl+V** (Cmd on Mac); the copy appears next to it. Or drag the hob from **Appliances** again.'),
('E', 'how do I make a hole in the countertop for the sink',
 'The hole is set on the sink in the catalogue, not on the cabinet:\n\n1. Go to **Catalogue** → **Appliances** and open your sink.\n2. Fill in **Countertop cutout width** and **Cutout depth** (a little smaller than the sink, e.g. 560 × 440 for a 600 × 450 sink).\n3. Press **Save**.\n\nEvery kitchen where that sink sits on a counter gets the hole.'),
('E', 'sink is showing as white box in 3d',
 'That sink has no working 3D model. Check **Catalogue** → **Appliances** → the sink → **Model file**: it must end in **.glb** or **.gltf** and must not start with "public/". If you\'re not sure which file to use, pick a sink that already shows correctly, or ask your admin.'),
('E', 'appliance price is coming in quote but customer is buying it himself',
 'Set the price of that appliance to 0 in **Catalogue** → **Appliances** → open it → **Price** → **Save**. Appliances already placed keep the price they were added with, so delete it from this kitchen and add it again.'),
('F', 'floor pe tiles kaise lagaye',
 '1. Click **Surfaces** on the left tool rail.\n2. Tap the **Floor** row.\n3. Pick a tile (tabs Tiles, Stone, Wood…).\n4. To show tile joints, tick **Lay as tiles**, then choose the size (e.g. 600×1200). For marble, stone or a plain colour you also choose **Straight** or **Offset (brick)** and the grout width and colour; a tile photo already has its grout, so only the size changes.'),
('F', 'backsplash tiles only behind the counter',
 "Use **Surfaces** → the wall's row (e.g. **North wall**) → pick the tile. The area hidden behind cabinets has its own **Behind units:** choice; leave it as **not finished** and that area isn't charged. Only the visible wall is priced."),
('F', 'how to change countertop granite',
 "**Surfaces** → **Countertop / slab** row → pick the slab (tabs Granite, Marble, Quartz…). For a different shade, choose **Custom shade** under **Colour**. Tick **Charge for it on the quote** only if you're supplying the slab."),
('F', "homeowner will buy granite himself, don't add in quote",
 'In **Surfaces**, leave **Charge for it on the quote** unticked under **Countertop / slab**. The slab still shows in the design and prints on the quote as "by homeowner" at ₹0.'),
('F', 'tiling is done by civil contractor, remove floor and wall cost from quote',
 'In **Surfaces**, untick **Charge floor, walls and ceiling on the quote** at the top. The finishes still show in the design; the quote shows them as not charged.'),
('F', "added a new tile photo in catalogue but it's not showing in floor options",
 'The floor list shows finishes whose **Finish type** suits floors (e.g. Vitrified tile, Ceramic tile, Marble, Granite, Wooden flooring). Check **Catalogue** → **Finishes** → your tile → **Finish type**, and **Save**. Or tick **Show all finishes** in the floor picker.'),
('H', 'give 5% discount on the quote',
 '1. Open the quote (**Quote** in the top bar, or **Finalise quote**).\n2. Under **Discount**, choose **%** and type **5**. For a fixed amount instead, choose **₹ amount**.\n3. The quote now shows **Subtotal**, **Discount (5%)** and the lower **Grand Total**.\n4. **Freeze** a new version and send it.\n\nThe discount comes out of your margin; the **Cost** view shows what you still make.'),
('F', 'how to add lights under the cabinets',
 '1. Click **Lights** on the left tool rail.\n2. Press **Add** next to a strip light in your list.\n3. Select it. In its settings set **Mounted on** → **On a cabinet** and choose the cabinet.\n\nLights are shown but not charged unless you tick **Charge electrical work**.'),
('F', 'where do I set the default finish for all new kitchens',
 '**Catalogue** → **Default kitchen style**: set the finish, colour, handle and board for base, wall and tall cabinets. Kitchens without their own **Style** use these, and each kitchen can change its own with **Style**.'),
('F', 'Style changed the cabinets but one cabinet did not change',
 'That cabinet was set by hand, so it keeps its own finish. When you change the style, the message offers **Change it too**. Or select that cabinet and change its **Finish** row directly.'),
('G', 'how to see 3d',
 'Click **3D** at the top of the design screen. In **Free orbit**, drag to turn the room and scroll or pinch to zoom. To stand inside the room, choose a camera under **Look from**.'),
('G', 'how to see one wall straight with measurements',
 'Click **Elevation** at the top, choose **Drawing**, then pick the wall: **North**, **East**, **South** or **West**. **Top view** shows the plan from above.'),
('G', 'how to add a camera',
 '1. Click **Cameras** on the left tool rail.\n2. Press **+ Add**; a camera appears in the middle of the room.\n3. Drag it on the plan to where a person would stand, and drag its small handle to aim it.\n4. Set **Height** (about 1500 mm is eye level) and **Tilt**.\n5. In **3D**, choose it under **Look from**.'),
('G', 'how to save the 3d angle I like',
 'In **3D**, choose a camera under **Look from**, drag to look around until it looks right, then press **Save this view**. That camera will open at this view next time.'),
('G', 'how to take 360 photo',
 'In **3D**, open **360° photos**, choose the camera under **360° photo for**, and press **Capture 360°**. Then press **View 360°** to look around. **Capture again** replaces it.'),
('G', 'how to show the design to customer without them seeing my cost',
 'Press **Present** in the top bar (on a phone: **…** → **Present to customer**). It shows **3D walkthrough** and **Floor plan** only. Nothing can be moved, and the price stays hidden until you press **Reveal price**. **Back to design** returns.'),
('G', 'how do I get a realistic photo of the kitchen for the customer',
 "1. Add a camera if there isn't one: **Cameras** in the left tools, then place it where you'd stand.\n2. Open the **3D** tab. Stand at **Camera 1**, look where you want, and press **Save this view**.\n3. Choose **Bare** or **Styled**, then press **Make image**.\n4. Wait 20–60 seconds; the picture opens when it's ready.\n\nEvery picture is kept under **Images** in the 3D tab, with **Download**."),
('G', 'can I move or edit cabinets in 3D',
 "You can click a cabinet in 3D to select it; its settings open from the right edge. To move items, use the **Plan** tab; that's where dragging works."),
('H', 'how do I make the quote',
 '1. Press **Finalise quote** at the bottom right of the design screen.\n2. Check the lines and set your margin under **Your pricing**.\n3. Press **Freeze quote**; this saves Quote v1 as a fixed version.\n4. Press **Download PDF** or **Share on WhatsApp**.\n\nThen move the customer to **Quote sent** on the Customers page.'),
('H', 'quotation bhejna hai whatsapp pe',
 'Design screen par **Finalise quote** dabayiye, phir **Freeze quote**. Uske baad **Share on WhatsApp** dabayiye. Customer ka number pehle se aa jayega; kisi aur number par bhejna ho to **A different number, just this once** chuniye.'),
('H', 'margin kahan change hota hai',
 'Open the quote (**Quote** in the top bar, or click the **Total**). Expand **Your pricing (not shown to the customer)** and change **Margin for this project (%)**. It applies to this kitchen only.'),
('H', 'I changed the design after sending quote, now what',
 "That's normal. The quote card now says the customer is holding the old version. Press **Freeze v2** (or the next number) to make a new version, then send it. Old versions stay under **All frozen versions**."),
('H', 'where to find the quote I sent last week',
 "Open that customer's design and open the quote panel (**Quote** in the top bar). Under **All frozen versions**, **Choose a version…**, then **Download PDF (vN)**."),
('H', 'add transport charges in quote',
 '- **For every job:** **Rate card** → **Labour and other charges** → **+ Add a charge** → name it, enter the amount, choose **lump sum** → **Save rates**.\n- **For this kitchen only:** open the quote → **Your pricing** → **Labour and other charges** → **Customise for this project**.'),
('H', 'does the quote include GST',
 "No. The app doesn't add GST automatically. You can print your GSTIN on the PDF: **Settings** → **GSTIN (optional)** → tick **Print the GSTIN on quotes** → **Save**."),
('H', 'price showing ₹0 for some cabinet',
 "Usually its board isn't on your Rate card. Open **Cutting list**; a message names the cabinet and board. Then add that board in **Rate card** → **Boards** → **+ Add board** → **Save rates**, or select the cabinet and choose another **Board**."),
('I', 'cutting list kahan milegi',
 "On the design screen, press **Cutting list** in the top bar (on a phone: **…** → **Cutting list**). You can also open it from **Production** → **Cutting list**, or a customer card's **…** menu → **Cutting list**."),
('I', 'carpenter wants the cutting list in excel',
 'Open the **Cutting list** and press **Excel sheet** at the top. **Cutting list PDF** prints it with sheet layouts, and **Part labels PDF** prints stickers for every piece.'),
('I', 'cutting list for the approved quote not current design',
 'Open the **Cutting list** and, at the top, change **Current design** to the frozen quote version the customer approved.'),
('I', 'cutting list says built on assumed construction',
 "Your Workshop settings aren't confirmed yet. Press **Workshop settings** (or go to **Workshop**), check each setting with your carpenter, tick **My carpenter has confirmed these settings**, and press **Save**."),
('I', 'how to add filler or skirting to cutting list',
 "Open the **Cutting list**, go to **Loose parts**, and press **Add part**. Enter **Name**, **Length**, **Width**, **Qty** and **Board** (in mm). It's cut and priced like any panel."),
('I', 'job is ready to start in workshop how to mark',
 'Go to **Production** and press **Start production** on that job. It moves to **In production**. After fitting, press **Mark installed**.'),
('I', 'change board of all cabinets to plywood',
 'Quickest: **Style** in the top bar → set **Carcass board** for base, wall and tall cabinets. Or select any cabinet → **Panels & boards…** → choose the board → **Use this carcass board for every cabinet**. That applies it straight away (Undo reverses it in one step).'),
('J', 'how to put my company logo on quote',
 "Go to **Settings** → **Logo** → **Upload logo** and choose a PNG or JPG. A wide logo on a white or transparent background prints best. It's printed at the top of your quote PDFs."),
('J', 'how to change labour rate',
 "Go to **Rate card** → **Labour and other charges**, change the amount (and whether it's **per sq ft**, **per cabinet** or **lump sum**), then press **Save rates**. Open quotes update; frozen quotes keep their old rates."),
('J', 'what is this yellow banner saying sample rates',
 "Your Rate card still has the starting sample prices. Go to **Rate card**, enter your real labour, hardware, board and glass prices, and press **Save rates**. Don't send a real quote until you have."),
('J', 'how to add new laminate finish',
 '**Catalogue** → **Finishes** → **New finish**. Enter the name, brand and code, set **Finish type** to Laminate, upload a **Swatch photo** (or pick a colour), enter **Price (₹ per m²)**, and press **Add finish**.'),
('J', 'I messed up my catalogue can I reset it',
 'Yes, if you saved a default earlier: **Catalogue** → **Your default catalogue** → **Go back to my default**. It resets edited items and brings back deleted ones; items you added since are kept. Use **Save as my default** whenever the catalogue is how you like it.'),
('J', 'how to change many cabinet prices at once',
 '**Catalogue** → **Cabinets** → **Bulk edit via Excel** → **Download for editing**. Change the prices in Excel, then press **Upload edited file**.'),
('J', 'forgot password',
 "1. On the sign-in page, press **Forgot password?** (under the password box).\n2. Type the email you sign in with → **Send reset link**.\n3. Open the link in the email (check spam; it works once).\n4. On **Set a new password**, type the new password twice → **Save new password**.\n\nIf the link has expired, the sign-in page tells you; send a new one."),
('J', 'my colleague wants to use the app',
 "They can sign up from the sign-in screen with **Create an account**, then confirm their email. They'll see **Waiting for access** until your admin adds them to your business; after that, **Check again** lets them in."),
('K', 'can I copy this kitchen design for another customer',
 "Not yet: a design can't be copied to another customer. Create the new customer and build their design. **Style** and your default catalogue make it quick to get the same finishes."),
('K', 'how to select many cabinets together',
 "Selecting several items at once isn't available. To change many at once:\n\n- **Finishes, handles, board:** use **Style** in the top bar.\n- **Panels:** use **Copy these panels to every …** in the Cabinet Designer."),
('K', 'delete',
 'What would you like to delete: an item in the design (cabinet, appliance, pillar, door, light, camera), a catalogue item, or a customer?'),
('K', "it's not working",
 'Sorry about that. What were you trying to do, and what happened? For example, "I can\'t drag a cabinet" or "the quote shows ₹0".'),
('K', 'my changes disappeared after I came back',
 "Check the top bar: if it said **Not saved**, the last changes didn't reach the server (usually internet). Reopen the design and redo them; watch for **Saved**. Undo history is cleared when you reopen a design."),
]

assert len(QA) == 100, len(QA)
out = sys.argv[1]
os.makedirs(out, exist_ok=True)
with open(os.path.join(out, 'qna.jsonl'), 'w') as f:
    for _, q, a in QA:
        f.write(json.dumps({"messages": [{"role": "system", "content": SYSTEM}, {"role": "user", "content": q}, {"role": "assistant", "content": a}]}, ensure_ascii=False) + "\n")
GROUPS = {"A": "Getting started and finding your way", "B": "Customers and stages", "C": "Room, pillars, doors and windows",
          "D": "Cabinets", "E": "Appliances and the sink", "F": "Style, surfaces, tiles, slab and lights",
          "G": "3D, elevation, cameras and present", "H": "Quote", "I": "Cutting list, Cabinet Designer and production",
          "J": "Setup: catalogue, rates, workshop, settings, account", "K": "Can't do, troubleshooting and unclear questions"}
with open(os.path.join(out, 'QNA.md'), 'w') as f:
    f.write("# KitchenDesignBiz assistant — 100 questions and answers\n\nFor fine-tuning (the same pairs are in `qna.jsonl`, chat format with the system prompt below) and for reviewing by hand.\n\n**System prompt used in every example:**\n\n> " + SYSTEM + "\n")
    n = 0
    for g, title in GROUPS.items():
        f.write(f"\n## {g}. {title}\n")
        for gg, q, a in QA:
            if gg != g: continue
            n += 1
            f.write(f"\n### {n}. {q}\n\n{a}\n")
print("ok", len(QA))
